# illustrative field encryption with AAD (not in repo; uses 'cryptography' package)
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

def seal(dek: bytes, tenant_id: str, row_id: str, plaintext: bytes) -> bytes:
    nonce = os.urandom(12)
    return nonce + AESGCM(dek).encrypt(nonce, plaintext, f"{tenant_id}:{row_id}".encode())
